INSERT INTO Card_Info (ID, SuitID, Name, Description) VALUES (1, 1, N'Bộ thẻ huyệt ma kiến', N'Vô số dũng sĩ từ mọi nơi đều đang tập hợp tại đây, cánh rừng ma quái.Mọi người cần phải tìm ra nơi cư ngụ của loài kiến ma "Huyệt ma kiến" . Qua những trận chiến gian nan, cuối cùng họ cũng hạ được nữ vương kiến và lấy được bộ thẻ phép thuật!');
INSERT INTO Card_Info (ID, SuitID, Name, Description) VALUES (2, 1, N'Bộ thẻ vương thành gà', N'Sau khi hạ được Quốc vương xấu tính của vương thành gà, các dũng sĩ đã chế tạo thành công bộ thẻ phép thuật nhưng chẳng may Mathias đã cướp chúng đi.Giờ mọi người phải cùng hợp sức để cướp lại bộ thẻ!');
INSERT INTO Card_Info (ID, SuitID, Name, Description) VALUES (3, 1, N'Bộ thẻ bộ lạc tà thần', N'Tương truyền rằng có một bộ thẻ đã ghi lại những bí mật kinh thiên động địa của cây thương cổ đang bị lưu lạc trong một bộ lạc bị khống chế bởi thế lực đen tối. Hãy mau đến đó tìm lại bộ thẻ này!');
INSERT INTO Card_Info (ID, SuitID, Name, Description) VALUES (4, 1, N'Bộ thẻ pháo đài hắc ám', N'Trong pháo đài hắc ám,không hiểu sao luôn phát ra  thứ ánh sáng lấp lánh, thì ra đó là ánh sáng của bộ thẻ thần bí.Nếu lấy lại được và sử dụng đúng cách sẽ giúp pháo đài trở lại sự yên bình.');
INSERT INTO Card_Info (ID, SuitID, Name, Description) VALUES (5, 0, N'Bộ thẻ vũ khí thần bí', N'Các dũng sĩ đã tìm thấy trong rừng sâu dấu tích 4 loại vũ khí.Tương truyền do không thể khống chế sức mạnh nên vũ khí đã bị tiêu hủy.Nếu như bây giờ chúng ta tìm ra 4 loại thẻ đặc biệt thì có thể triệu hồi sức mạnh của vũ khí.');
INSERT INTO Card_Info (ID, SuitID, Name, Description) VALUES (6, 1, N'Bộ thẻ Goblin', N'Tà Diệm Long cuối cùng đã bị hạ, hãy xem có thứ gì rơi ra kìa.Các dũng sĩ chạy đến xem thì phát hiện ra bộ thẻ Goblin ghi cháp những bí mật. Nhưng đúng lúc này xào huyệt sụp đổ, các dũng sĩ đã không thể quay trở ra.');
INSERT INTO Card_Info (ID, SuitID, Name, Description) VALUES (7, 1, N'Bộ thẻ giải cứu gà con', N'Giải cứu những chú gà vàng thật xinh xắn sẽ được tặng những bộ thẻ thần bí. Nhưng không chỉ có 1 con gà mái xấu xí, các dũng sĩ, ãy mau lên đường cứu những chú gà vàng nào!');
INSERT INTO Card_Info (ID, SuitID, Name, Description) VALUES (8, 1, N'Bộ thẻ Đấu trường gà', N'Vương quốc gà đã tổ chức thành công đại hội thể thao đầu tiên. Và lần này cũng đặc biệt sản xuất bộ thẻ Đấu trường gà. Ngoài việc dùng làm kỹ niệm, bộ thẻ còn mang đến cho bạn sự may mắn.Bạn có phải là người của chiến thắng không?');
INSERT INTO Card_Info (ID, SuitID, Name, Description) VALUES (9, 0, N'Bộ thẻ Ngũ Thần Binh', N'Ngũ đại thần đang cai quản và giữ thế cân bằng cho thế giới, thế nhưng vũ khí họ sử dụng lại lưu lạc trong nhân gian. Tương truyền nếu tập hợp được cùng lúc 5 vũ khí này sẽ có sức mạnh vô song!');
INSERT INTO Card_Info (ID, SuitID, Name, Description) VALUES (10, 1, N'Bộ thẻ Vòng xoáy thời gian', N'Vậy là tất cả những chiến tranh đều do bác học Vẹt mà ra. Các chiến sỹ trận mạc đã tặng những dũng sỹ của chúng ta thẻ bài quý được cất giữ đã lâu nhằm tỏ lòng biết ơn.');
INSERT INTO Card_Info (ID, SuitID, Name, Description) VALUES (11, 1, N'Thẻ Đấu Trường Dũng Sĩ', N'Nghe nói trong đấu trường xưa có 1 bộ thẻ Đấu Trường Dũng Sĩ có uy lực rất mạnh, không thể để chúng rơi vào tay thế lực đen tối, các dũng sĩ hãy bắt đầu cuộc hành trình của mình');
INSERT INTO Card_Info (ID, SuitID, Name, Description) VALUES (12, 0, N'Bộ Thẻ Truyền Thuyết Khai Hoang', N'Vũ khí ẩn chứa lý tưởng và quá khứ của dũng sĩ. Họ đã chế tạo bộ thẻ bài này để kỷ niệm thời thanh xuân của mình, sở hữu có nó sẽ nhận được chúc phúc.');
INSERT INTO Card_Info (ID, SuitID, Name, Description) VALUES (13, 0, N'Bộ Thẻ Đại Sư Vũ Khí', N'Thần khí có sức mạnh to lớn, sở hữu chúng sẽ trở thành nhân tài kiệt xuất. Chủ nhân thần khí chế tạo bộ thẻ bài này để tặng cho người có duyên, mong rằng có thể giúp họ trưởng thành!');
INSERT INTO Card_Info (ID, SuitID, Name, Description) VALUES (14, 0, N'Bộ Thẻ Thần Vực', N'Sau cuộc chiến phong ấn ma, bộ thẻ Thần Vực lưu lạc nhân gian, bị tà ma cướp mất, chúng ẩn nấp khắp nơi để chờ thời cơ phản công. Các dng sĩ vẫn luôn tìm kiếm bộ thẻ, hy vọng dập tắt âm mưu của chúng.');
INSERT INTO Card_Info (ID, SuitID, Name, Description) VALUES (15, 0, N'Bộ Thẻ May Mắn', N'Dù cuộc sống vẫn luôn tràn ngập phiền não, nhưng chỉ cần mỉm cười may mắn sẽ đến. Bộ thẻ bài tặng may mắn cho dũng sĩ, nỗi buồn sẽ kết thúc từ đây!');
INSERT INTO Card_Info (ID, SuitID, Name, Description) VALUES (16, 0, N'Bộ Thẻ Vui Vẻ', N'Cuộc sống như kính vạn hoa, nhiều màu sắc rực rỡ. Nhìn xem, nơi đây tràn ngập không khí lễ hội, chúng ta hãy cùng ca múa, trao niềm vui đến mọi ngõ ngách của thế giới.');
INSERT INTO Card_Info (ID, SuitID, Name, Description) VALUES (17, 0, N'Bộ Thẻ Thần Thương', N'Hỡi nhà mạo hiểm dũng cảm, hãy dùng Thần Thương trong tay chứng tỏ sức mạnh!');
INSERT INTO Card_Info (ID, SuitID, Name, Description) VALUES (18, 0, N'Bộ Thẻ Chiến Thần', N'Chiến Thần, từng dùng cây búa trong tay lập nên uy danh hiển hách. Chiến Chư Thần mới lại sắp bắt đầu, hỡi hậu duệ của chiến thần, các bạn đã sẵn sàng?');
